import { createRequestHandler } from 'react-router'
import { dispatchApiRequest } from '@/app/server/apiRouter'
import { withDocumentNoStore } from './responseHeaders'

declare module 'react-router' {
  interface AppLoadContext {
    cloudflare: {
      env: CloudflareEnv
      ctx: ExecutionContext
    }
  }
}

const requestHandler = createRequestHandler(
  () => import('virtual:react-router/server-build') as Promise<any>,
  process.env.NODE_ENV ?? 'production',
)

export default {
  async fetch(request, env, ctx) {
    const apiResponse = await dispatchApiRequest(request)
    if (apiResponse) return apiResponse

    const response = await requestHandler(request, {
      cloudflare: { env, ctx },
    })
    return withDocumentNoStore(response)
  },
} satisfies ExportedHandler<CloudflareEnv>

export function withDocumentNoStore(response: Response) {
  const contentType = response.headers.get('Content-Type') ?? ''
  if (!contentType.toLowerCase().includes('text/html')) return response

  const headers = new Headers(response.headers)
  headers.set('Cache-Control', 'no-store')
  return new Response(response.body, {
    headers,
    status: response.status,
    statusText: response.statusText,
  })
}
import { describe, expect, it } from 'vitest'
import { withDocumentNoStore } from './responseHeaders'

describe('worker response headers', () => {
  it('marks HTML responses as no-store at the worker boundary', async () => {
    const response = withDocumentNoStore(
      new Response('<!doctype html>', {
        headers: { 'Content-Type': 'text/html; charset=utf-8' },
      }),
    )

    expect(response.headers.get('Cache-Control')).toBe('no-store')
    await expect(response.text()).resolves.toBe('<!doctype html>')
  })

  it('leaves non-document responses alone', () => {
    const response = new Response('{}', {
      headers: { 'Content-Type': 'application/json', 'Cache-Control': 'max-age=60' },
    })

    expect(withDocumentNoStore(response)).toBe(response)
  })
})

